// Generated by `just generate` from `src/plugins/dotclaude-sessions/slices/usage/domain/scan.ts`. Edit the source and run `just generate`.
// One transcript file of the usage report: its calls, its tool uses, and its runs, added to the sums.

import path from "node:path";
import type { Store } from "../ports.ts";
import {
  bestUsage,
  briefSize,
  callCost,
  firstLine,
  resultText,
  tokens,
  windowOf,
} from "./parse.ts";
import { listedSkills, rereadOf, runRow } from "./runs.ts";
import { agentType, readEntries } from "./transcript.ts";
import { maxTurns, reserve, turnsFromText } from "./turns.ts";
import type { CallRow, MessageUsage, ReportSums, Scope } from "./types.ts";

/** The options of `scanFile`: the agents folder for `maxTurns`, and the context window. */
export type ScanOptions = {
  agentsDir: string | null;
  window: number | null;
};

/** Adds the transcript `file` to the sums `s`. Only the entries from `since` on count. */
export const scanFile = async (
  store: Store,
  file: string,
  s: ReportSums,
  since: Date,
  options: ScanOptions,
): Promise<void> => {
  const { agentsDir, window } = options;
  const type: string = await agentType(store, file);
  const limit = type === "main" ? null : await maxTurns(store, type, agentsDir);
  if (limit)
    s.limited.push({
      type,
      capped:
        turnsFromText((await store.read(file)) ?? "") >= limit - reserve(limit),
      ...(await briefSize(store, file)),
    });
  const seen = new Set<string | undefined>();
  let fileCost = 0;
  let resultTokens = 0;
  let handback = "";
  let wake = false;
  let hookContext = false;
  let firstPending = false;
  let lastCallAt: number | null = null;
  let lastModel: string | null | undefined = null;
  let compacted = false;
  let entrypoint: string | null = null;
  const rereads: number[] = [];
  const entries = await readEntries(store, file);
  const best = bestUsage(entries);
  for (const entry of entries) {
    // A line with no `timestamp` gives an invalid date, so each comparison with `since` is false.
    const when = new Date(entry.timestamp ?? Number.NaN);
    if (type === "main" && !entrypoint && entry.entrypoint && when >= since) {
      entrypoint = entry.entrypoint;
      s.entrypoints[entrypoint] = (s.entrypoints[entrypoint] ?? 0) + 1;
    }
    const m = entry.message;
    switch (entry.type) {
      case "assistant":
        if (when < since) break;
        if (entry.error === "rate_limit") s.limitHits += 1;
        // One API message can span several entries, one per content block,
        // so a tool call is counted by its own id and not by the message id.
        for (const b of Array.isArray(m?.content) ? m.content : []) {
          if (b.type !== "tool_use") continue;
          if (b.name === "Skill" && b.input?.skill && !seen.has(b.id)) {
            seen.add(b.id);
            s.skills[b.input.skill] = (s.skills[b.input.skill] ?? 0) + 1;
          }
          if (type === "main" && (b.name === "Agent" || b.name === "Task"))
            s.agentCalls.set(b.id, {
              description: b.input?.description ?? "",
              handback: "",
            });
          if (type !== "main" && b.name === "SubagentHandback")
            handback = firstLine(b.input?.message);
        }
        break;
      case "attachment":
        if (entry.attachment?.type === "skill_listing")
          for (const sk of listedSkills(entry.attachment))
            s.listed.set(
              sk.name,
              Math.max(s.listed.get(sk.name) ?? 0, sk.chars),
            );
        if (
          entry.attachment?.type === "hook_additional_context" &&
          entry.attachment.hookEvent !== "SessionStart"
        )
          hookContext = true;
        break;
      case "system":
        if (entry.subtype === "compact_boundary") compacted = true;
        break;
      case "user":
        if (type === "main") {
          const content = m?.content;
          if (when >= since)
            for (const b of Array.isArray(content) ? content : []) {
              if (b.type !== "tool_result") continue;
              const text = resultText(b.content);
              // Estimate with the shared token estimate, from content length.
              resultTokens += tokens(text);
              const call = s.agentCalls.get(b.tool_use_id);
              if (call) {
                call.handback = firstLine(text);
                call.agentId =
                  entry.toolUseResult?.agentId ??
                  text.match(/agentId: (\w+)/)?.[1];
              }
            }
          const toolResult =
            Array.isArray(content) &&
            content.some((b) => b.type === "tool_result");
          // Meta reminders without an origin continue the current turn.
          if (!toolResult && !(entry.isMeta && !entry.origin)) {
            const kind = entry.origin?.kind;
            wake = kind === "peer" || kind === "task-notification";
            firstPending = true;
            if (when >= since) {
              s.turns[wake ? "wake" : "other"] += 1;
              const ep = entrypoint ?? "unknown";
              if (wake) s.wakes[ep] = (s.wakes[ep] ?? 0) + 1;
            }
          }
          continue;
        }
        break;
    }
    if (entry.type !== "assistant" || !m?.usage) continue;
    if (when < since || seen.has(m.id)) continue;
    seen.add(m.id);
    const { usage, final } = best.get(m.id) as MessageUsage;
    s.output.tokens += usage.output_tokens ?? 0;
    s.output.messages += 1;
    if (!final) s.output.unfinished += 1;
    const c = callCost(m.model, usage);
    rereads.push(rereadOf(usage));
    const at = when.getTime();
    if (firstPending && lastCallAt !== null && at - lastCallAt < 300_000) {
      const b = s.first[hookContext ? "with" : "without"];
      b[0] += 1;
      b[1] += usage.cache_creation_input_tokens ?? 0;
      b[2] += c.context;
    }
    firstPending = false;
    lastCallAt = at;
    for (const it of usage.iterations ?? []) {
      if (it.type !== "advisor_message") continue;
      const a = callCost(it.model, it).total;
      s.advisor.calls += 1;
      s.advisor.cost += a;
      c.total += a;
    }
    s.total += c.total;
    fileCost += c.total;
    if (type === "main") s.mainTurns += 1;
    s.byAgent[type] = (s.byAgent[type] ?? 0) + c.total;
    if (c.context > (window ?? windowOf(m.model))) s.overWindow += c.total;
    if (c.rewrite) {
      const reason =
        lastModel === null
          ? "first"
          : compacted
            ? "compaction"
            : m.model !== lastModel
              ? "model"
              : null;
      if (reason) {
        s.expected[reason] += 1;
        s.expectedCost += c.write;
      } else s.rewrites += c.write;
    }
    lastModel = m.model;
    compacted = false;
    if (type === "main" && wake) s.wakeCost += c.total;
    const scopes: Scope[] = type === "main" ? ["all", "main"] : ["all"];
    for (const key of scopes) {
      s.cache[key][0] += c.context;
      s.cache[key][1] += c.read;
    }
  }
  const id = path.basename(file, ".jsonl").replace(/^agent-/, "");
  if (rereads.length) {
    const row: CallRow = runRow(id, type, rereads);
    s.callRuns.push(row);
  }
  if (type === "main") s.sessionResultTokens.push(resultTokens);
  else {
    s.runsByType[type] = (s.runsByType[type] ?? 0) + 1;
    s.runs.push({
      id,
      type,
      cost: fileCost,
      handback,
      at: await store.mtime(file),
    });
  }
};
